    متغير كومة = []
    من_أجل (حرف_مفتاح في نص) {
        إذا (حرف_مفتاح == '(' أو حرف_مفتاح == '[' أو حرف_مفتاح == '{') {
            أضف(كومة, حرف_مفتاح)
        } وإلا إذا (حرف_مفتاح == ')' أو حرف_مفتاح == ']' أو حرف_مفتاح == '}') {
            إذا (طول(كومة) == ٠) {
                ارجع خطأ
            }
            متغير حرف_قمة = انزع(كومة)
            إذا (حرف_مفتاح == ')' و حرف_قمة != '(') أو (حرف_مفتاح == ']' و حرف_قمة != '[') أو (حرف_مفتاح == '}' و حرف_قمة != '{') {
                ارجع خطأ
            }
        }
    }
    ارجع طول(كومة) == ٠
}

**ملاحظة:** تم تغيير اسم المتغير "حرف" إلى "حرف_مفتاح" لأن "حرف" هو اسم دالة جاهزة في ضاد.

